(* keep_hierarchy,
// keep *) (CP1-R10 face_guard; QC-KITS 10-25: without it Yosys flattened the bound kits and opt_merge folded replicated
// per-destination boundary registers -- QC sle_ctl b_hw_hc1/2/3_o all fed from the hc0 flops: face_guard 7,853 fails
// (feedthrough 4,859 / shared 2,937) -> 179 with it, the rest = plan-vs-bound width spares).
(* keep_hierarchy, keep *)
module ot_dp_st #(parameter integer W = 1) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [W-1:0] d,
    input  wire         ea,
    output reg  [W-1:0] q,
    output reg          eq
);
    always @(posedge clk) q <= d;
    always @(posedge clk or negedge rst_n)
        if (!rst_n) eq <= 1'b0; else eq <= ea;
endmodule

module ot_dp_dly #(parameter integer W = 1, parameter integer D = 1) (
    input  wire         clk,
    input  wire [W-1:0] d,
    output wire [W-1:0] q
);
    reg [W-1:0] r [0:D-1];
    integer i;
    always @(posedge clk) begin
        r[0] <= d;
        for (i = 1; i < D; i = i + 1) r[i] <= r[i-1];
    end
    assign q = r[D-1];
endmodule

module qfd_dv_sram_bank64 #(parameter integer W=546)(
 input wire clk,r_ce_in,w_ce_in,input wire[4:0] r_addr_in,w_addr_in,
 output wire[W-1:0] rd_out,input wire[W-1:0] wd_in,w_mask_in
);
 localparam integer N=(W+63)/64,P=64*N-W;
 wire[64*N-1:0] data={{P{1'b0}},wd_in},mask={{P{1'b0}},w_mask_in};
 wire[64*N-1:0] result;
 generate for(genvar b=0;b<N;b=b+1) begin:g_bank
  ot_sram_1r1w_32x64_m1 u_m(.clk(clk),.r_ce_in(r_ce_in),.r_addr_in(r_addr_in),.rd_out(result[64*b+:64]),
   .w_ce_in(w_ce_in),.w_addr_in(w_addr_in),.wd_in(data[64*b+:64]),.w_mask_in(mask[64*b+:64]));
 end endgenerate
 assign rd_out=result[W-1:0];

 initial if(W<1||W>546) $fatal(1,"SRAM_BANK64_WIDTH");

endmodule

(* keep_hierarchy="yes" *) module qfd_dv_station_out #(parameter integer W=16,ID=0)(input wire ck,rst_n,input wire[W-1:0] d,output reg[W-1:0] q);
always @(posedge ck or negedge rst_n) if(!rst_n) q<=0;else q<=d;
endmodule

module qfd_dv_s8s_sram_lookahead #(parameter integer W = 512, parameter integer MUT = 0, parameter integer G = 12) (
    input wire ck, input wire write, input wire [4:0] wa, ra,
    input wire [W-1:0] wd, output wire [W-1:0] q
);
    wire same = write && wa == ra;
    wire [W-1:0] mq;
    reg [W-1:0] bypass_data;
    always @(posedge ck) bypass_data <= wd;
    qfd_dv_sram_bank64 #(.W(W)) u_m (.clk(ck), .r_ce_in(!same), .r_addr_in(ra), .rd_out(mq),
        .w_ce_in(write), .w_addr_in(wa), .wd_in(wd), .w_mask_in({W{1'b1}}));
    genvar g;
    generate for (g = 0; g < (W+G-1)/G; g = g + 1) begin : g_out
        localparam integer B = ((W-G*g) < G) ? W-G*g : G;
        wire sel;
        (* keep_hierarchy = "yes" *) qfd_dv_kept_bit #(.ID(g)) u_sel (.ck(ck), .d(same && MUT == 0), .q(sel));
        assign q[G*g +: B] = sel ? bypass_data[G*g +: B] : mq[G*g +: B];
    end endgenerate
`ifndef SYNTHESIS
    initial if (W > 546 || W < 1) $fatal(1, "SRAM_LOOKAHEAD_WIDTH");
`endif
endmodule
